def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda interval: (interval[0], interval[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adjacency = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}
    seen_edges = set()

    for source, dest in edges:
        if source == dest:
            raise ValueError("self-loop detected")
        if (source, dest) in seen_edges:
            continue
        seen_edges.add((source, dest))
        adjacency[source].add(dest)
        in_degree[dest] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for dest in adjacency[node]:
            in_degree[dest] -= 1
            if in_degree[dest] == 0:
                heapq.heappush(heap, dest)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")

    return order

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be a positive integer")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("weight must satisfy 1 <= weight <= limit")
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re

_KEY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')


def parse_env(text):
    result = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid environment line: {line!r}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        if not _KEY_RE.match(key):
            raise ValueError(f"Invalid environment key: {key!r}")
        result[key] = value
    return result

def parse_sse(chunks):
    stream = b''.join(chunks).decode('utf-8')
    events = []
    current = []
    n = len(stream)
    i = 0

    while i < n:
        # Grab line content up to the next line ending (LF or CRLF).
        j = i
        while j < n and stream[j] not in ('\r', '\n'):
            j += 1

        # No line ending left: the trailing event is unterminated -> ignore it.
        if j >= n:
            break

        line = stream[i:j]

        # Advance past the ending, collapsing CRLF to a single step.
        if stream[j] == '\r':
            i = j + 2 if j + 1 < n and stream[j + 1] == '\n' else j + 1
        else:
            i = j + 1

        # A blank line dispatches the accumulated event.
        if line == '':
            if current:
                data = '\n'.join(current)
                if data == '[DONE]':
                    return events          # dispatch, exclude [DONE], stop
                events.append(data)
                current = []
        # Comment lines (start with ':') and colon-less lines are ignored.
        elif not line.startswith(':') and ':' in line:
            field, _, value = line.partition(':')
            if value.startswith(' '):
                value = value[1:]
            if field == 'data':
                current.append(value)

    return events

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    - attempt: nonnegative integer
    - base, cap: finite nonnegative numbers
    """
    # --- validate arguments (raise for negatives) ---
    if attempt < 0:
        raise ValueError("attempt must be a nonnegative integer")
    if base < 0:
        raise ValueError("base must be nonnegative")
    if cap < 0:
        raise ValueError("cap must be nonnegative")

    # --- zero shortcuts: never build 2**attempt ---
    if base == 0 or cap == 0:
        return 0.0

    # Compare base * 2**attempt with cap via logarithms so we never form
    # the gigantic integer 2**attempt (e.g. attempt = 10**9).
    #   base * 2**attempt >= cap
    # <=> log2(base) + attempt >= log2(cap)
    # cap is finite and positive here, so this comparison can't overflow.
    if attempt + math.log2(base) >= math.log2(cap):
        # base * 2**attempt dominates cap (even if it would overflow),
        # so the minimum is cap.
        return float(cap)

    # Here base * 2**attempt < cap <= float max, so the true product fits
    # in a float and can be computed exactly without overflow.
    try:
        return float(math.ldexp(base, attempt))
    except OverflowError:
        return float(cap)

def fifo_admit(active, queued, budget, slots):
    if any(reservation > budget for reservation in queued):
        raise ValueError("A queued reservation exceeds the whole budget")

    used_tokens = sum(active)
    used_slots = len(active)

    admitted = []
    remaining = []
    for index, reservation in enumerate(queued):
        if used_slots + 1 <= slots and used_tokens + reservation <= budget:
            admitted.append(reservation)
            used_tokens += reservation
            used_slots += 1
        else:
            remaining = list(queued[index:])
            break

    return admitted, remaining
